/// <summary>
/// PaffH 20.08.25
/// </summary>
public void init()
{
    next init();

    if (this.args() &&
        this.args().parmObject() is NDXBVSearchContract)
    {
        nDXBVSearchContract = this.args().parmObject() as NDXBVSearchContract;
    }
}

/// <summary>
/// PaffH 20.08.25
/// last modified: PaffH 12.09.25
/// </summary>
public void run()
{
    next run();

    if (nDXBVSearchContract)
    {
        if (nDXBVSearchContract.parmSubject())
        {
            KCS_KBVBuildingProjectTable.KCS_KBVSubject = nDXBVSearchContract.parmSubject();
        }
        if (nDXBVSearchContract.parmCity())
        {
            KCS_KBVBuildingProjectTable.AddressCity = nDXBVSearchContract.parmCity();
        }
        if (NDXBVSearchContract.parmProjectAddressZipCode())
        {
            KCS_KBVBuildingProjectTable.AddressZipCodeId = NDXBVSearchContract.parmProjectAddressZipCode();
        }
        if (nDXBVSearchContract.parmrecIdContactPerson())
        {
            ContactPerson contactPersonLocal = ContactPerson::findRecId(nDXBVSearchContract.parmrecIdContactPerson());
            DirPartyTable dirPartyTableLocal = DirPartyTable::findRec(contactPersonLocal.ContactForParty);

            relationDirPartyId1 = dirPartyTableLocal.RecId;
            DirPartyId1.value(dirPartyTableLocal.RecId);
            ContactPersonId1.text(contactPersonLocal.ContactPersonId);
        }
    }
}

